package match

import (
	"fmt"
	"strings"

	"romcure/internal/store"
)

// MatchTracks identifies a disc image from the hashes of its extracted
// tracks (a CHD's contents). A DAT game matches only when every one of its
// non-.cue ROMs is covered by a track (CRC32+size+SHA1 when the DAT has one)
// and no track is left over: a partial match would link a wrong disc as
// "verified". The .cue is ignored because its text is regenerated by the
// extractor and never matches Redump's byte for byte.
//
// ok is false when no DAT game fully matches.
func MatchTracks(db *store.DB, systemID string, tracks []store.CHDTrack) (Result, bool, error) {
	if len(tracks) == 0 {
		return Result{}, false, nil
	}

	var candidates map[string]bool
	firstEntry := map[string]int64{}
	for i, t := range tracks {
		rows, err := db.Query(`SELECT id, game_name, sha1 FROM dat_entries
			WHERE system_id = ? AND crc32 = ? AND size = ?`, systemID, t.CRC32, t.Size)
		if err != nil {
			return Result{}, false, fmt.Errorf("match track %s: %w", t.Name, err)
		}
		names := map[string]bool{}
		for rows.Next() {
			var id int64
			var name string
			var sha1 *string
			if err := rows.Scan(&id, &name, &sha1); err != nil {
				rows.Close()
				return Result{}, false, err
			}
			if sha1 != nil && *sha1 != "" && !strings.EqualFold(*sha1, t.SHA1) {
				continue
			}
			names[name] = true
			if i == 0 {
				if _, seen := firstEntry[name]; !seen {
					firstEntry[name] = id
				}
			}
		}
		rows.Close()
		if i == 0 {
			candidates = names
		} else {
			for n := range candidates {
				if !names[n] {
					delete(candidates, n)
				}
			}
		}
		if len(candidates) == 0 {
			return Result{}, false, nil
		}
	}

	// Pick a candidate whose ROM count equals the track count (so extra
	// ROMs in the DAT game that we don't have disqualify it).
	var best string
	for name := range candidates {
		var n int
		if err := db.QueryRow(`SELECT COUNT(*) FROM dat_entries WHERE system_id = ? AND game_name = ?
			AND lower(rom_name) NOT LIKE '%.cue' AND lower(rom_name) NOT LIKE '%.gdi'`, systemID, name).Scan(&n); err != nil {
			return Result{}, false, err
		}
		if n == len(tracks) && (best == "" || name < best) {
			best = name
		}
	}
	if best == "" {
		return Result{}, false, nil
	}

	info := classify(best)
	return Result{
		Confidence: ConfidenceDATVerified, Title: best, Region: info.region, Language: info.language,
		Revision: info.revision, IsBeta: info.isBeta, IsProto: info.isProto, IsDemo: info.isDemo, VariantPenalty: info.penalty,
		IsVerifiedDump: true, DatEntryID: firstEntry[best],
	}, true, nil
}

// TracksContentHash is the stable identity string for a track set (sorted
// by ordinal), used as the item's content hash so a verified CHD gets the
// same game key wherever it lives (spec §2.11).
func TracksContentHash(tracks []store.CHDTrack) string {
	parts := make([]string, len(tracks))
	for i, t := range tracks {
		parts[i] = t.CRC32
	}
	return strings.Join(parts, "+")
}
